select Distinct a."ItemCode",a."DocEntry",   a."DocNum",a."DocTotal",a."U_BelowCst",a."BPLId" from (  SELECT T1."ItemCode",T0."DocNum",T0."DocTotal",T0."CreateDate",T0."BPLId",T0."DocEntry",T0."CreateTS",T1."U_BelowCst" FROM OPDN T0 INNER JOIN PDN1 T1 on T0."DocEntry"=T1."DocEntry"   where length(T0."CreateTS")>5)as a    where  a."CreateDate"=CURRENT_DATE and a."U_BelowCst"='Yes' and a."BPLId" in ('1','3','5','9') and  LEFT(LPAD(a."CreateTS",6,'0'),4)>=TO_CHAR(ADD_SECONDS(CURRENT_TIMESTAMP,-60), 'HH24MI')
